const lastKnown = $input.item.json.records?.[0]?.fields;
const newPrice = $('Extract Price Data').item.json.new_price;
const threshold = $('Extract Price Data').item.json.PRICE_CHANGE_THRESHOLD;

if (!lastKnown) {
  return [{ json: {
    is_new_vendor: true,
    vendor_name: $('Extract Price Data').item.json.vendor_name,
    item_sku: $('Extract Price Data').item.json.item_sku,
    new_price: newPrice,
    currency: $('Extract Price Data').item.json.currency,
    change_pct: 0,
    cost_impact_monthly: 0,
    needs_alert: false,
    record_id: null
  }}];
}

const oldPrice = lastKnown['Last Known Price'] || lastKnown['Current Price'] || newPrice;
const monthlyVolume = lastKnown['Monthly Volume'] || 0;
const changePct = oldPrice > 0 ? ((newPrice - oldPrice) / oldPrice) * 100 : 0;
const monthlyImpact = (newPrice - oldPrice) * monthlyVolume;

return [{ json: {
  is_new_vendor: false,
  vendor_name: $('Extract Price Data').item.json.vendor_name,
  item_sku: $('Extract Price Data').item.json.item_sku,
  old_price: oldPrice,
  new_price: newPrice,
  currency: $('Extract Price Data').item.json.currency,
  change_pct: Math.round(changePct * 100) / 100,
  change_direction: changePct > 0 ? 'increase' : 'decrease',
  cost_impact_monthly: Math.round(monthlyImpact),
  monthly_volume: monthlyVolume,
  needs_alert: Math.abs(changePct) >= threshold,
  record_id: $input.item.json.records[0].id
}}];

