={
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "system",
      "content": "You are a procurement analyst. Given a vendor price change, write a 2-3 sentence analysis for the procurement team. Mention if they should negotiate, find alternatives, or accept. Be concise and practical."
    },
    {
      "role": "user",
      "content": "Vendor: {{ $json.vendor_name }}\nItem: {{ $json.item_sku }}\nPrice change: {{ $json.old_price }} → {{ $json.new_price }} {{ $json.currency }} ({{ $json.change_pct > 0 ? '+' : '' }}{{ $json.change_pct }}%)\nMonthly volume: {{ $json.monthly_volume }} units\nMonthly cost impact: {{ $json.currency }} {{ $json.cost_impact_monthly > 0 ? '+' : '' }}{{ $json.cost_impact_monthly }}"
    }
  ],
  "max_tokens": 200
}

={
