        { "type": "mrkdwn", "text": "*New Price:*\n{{ $('Calculate Price Change').item.json.currency }} {{ $('Calculate Price Change').item.json.new_price }} ({{ $('Calculate Price Change').item.json.change_pct > 0 ? '+' : '' }}{{ $('Calculate Price Change').item.json.change_pct }}%)" },
