      ]
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "*Analysis:*\n{{ $json.choices[0].message.content }}" }
    },
    {
      "type": "context",
      "elements": [{ "type": "mrkdwn", "text": "Vendor Price Monitor • FlowMind Labs" }]
    }
  ]
}
